const { remote } = require('webdriverio');

(async () => {
  const browser = await remote({
    hostname: '127.0.0.1',
    port: 4723,
    path: '/',
    capabilities: {
      platformName: 'iOS',
      'appium:automationName': 'XCUITest',
      'appium:udid': '972BE032-D676-4181-BFD4-07B3B9841186',
      'appium:bundleId': 'xyz.blueskyweb.app',
      'appium:noReset': true,
      'appium:shouldTerminateApp': false,
      'appium:autoLaunch': false,
    },
    logLevel: 'error',
  });

  const tap = async (x, y) => {
    await browser.execute('mobile: tap', { x, y });
  };

  // Tap "Open" in the "Open in Bluesky?" dialog
  await tap(262, 479);
  await new Promise(r => setTimeout(r, 2500));

  // Tap the bell (Notifications) icon in bottom nav
  await tap(270, 796);
  await new Promise(r => setTimeout(r, 2500));

  await browser.deleteSession();
  console.log('done');
})().catch(e => { console.error(e.message); process.exit(1); });

const { remote } = require('webdriverio');
const fs = require('fs');

(async () => {
  const browser = await remote({
    hostname: '127.0.0.1',
    port: 4723,
    path: '/',
    capabilities: {
      platformName: 'iOS',
      'appium:automationName': 'XCUITest',
      'appium:udid': '972BE032-D676-4181-BFD4-07B3B9841186',
      'appium:bundleId': 'xyz.blueskyweb.app',
      'appium:noReset': true,
      'appium:shouldTerminateApp': false,
      'appium:autoLaunch': false,
    },
    logLevel: 'error',
  });

  const src = await browser.getPageSource();
  fs.writeFileSync('/tmp/page.xml', src);

  const matches = [...src.matchAll(/label="([^"]*[Nn]otif[^"]*)"/g)].map(m => m[1]);
  console.log('notif labels:', JSON.stringify(matches.slice(0, 10)));

  let tapped = false;
  try {
    const el = await browser.$('~Notifications');
    if (await el.isExisting()) {
      await el.click();
      tapped = true;
      console.log('tapped ~Notifications');
    }
  } catch (e) {}
  if (!tapped) {
    try {
      const el = await browser.$('~Notifications tab');
      if (await el.isExisting()) { await el.click(); tapped = true; console.log('tapped ~Notifications tab'); }
    } catch (e) {}
  }
  if (!tapped) {
    await browser.execute('mobile: tap', { x: 270, y: 796 });
    console.log('tapped coords 270,796');
  }

  await new Promise(r => setTimeout(r, 2500));
  await browser.deleteSession();
  console.log('done');
})().catch(e => { console.error('ERR', e.message); process.exit(1); });

const { remote } = require('webdriverio');
const fs = require('fs');

(async () => {
  const browser = await remote({
    hostname: '127.0.0.1',
    port: 4723,
    path: '/',
    capabilities: {
      platformName: 'iOS',
      'appium:automationName': 'XCUITest',
      'appium:udid': '972BE032-D676-4181-BFD4-07B3B9841186',
      'appium:bundleId': 'xyz.blueskyweb.app',
      'appium:noReset': true,
      'appium:shouldTerminateApp': false,
      'appium:autoLaunch': false,
    },
    logLevel: 'error',
  });

  // Dismiss "Shared with You" sheet
  await browser.execute('mobile: tap', { x: 196, y: 751 });
  await new Promise(r => setTimeout(r, 1500));

  // Activate Bluesky
  await browser.execute('mobile: activateApp', { bundleId: 'xyz.blueskyweb.app' });
  await new Promise(r => setTimeout(r, 2500));

  const src = await browser.getPageSource();
  fs.writeFileSync('/tmp/page2.xml', src);
  const labels = [...src.matchAll(/label="([^"]+)"/g)].map(m => m[1]);
  console.log('labels:', JSON.stringify(labels.slice(0, 60)));

  let tapped = false;
  for (const name of ['Notifications', 'Notifications tab', 'notifications']) {
    try {
      const el = await browser.$('~' + name);
      if (await el.isExisting()) { await el.click(); tapped = true; console.log('tapped', name); break; }
    } catch (e) {}
  }
  if (!tapped) {
    await browser.execute('mobile: tap', { x: 270, y: 796 });
    console.log('tapped coords');
  }

  await new Promise(r => setTimeout(r, 2500));
  await browser.deleteSession();
  console.log('done');
})().catch(e => { console.error('ERR', e.message); process.exit(1); });

const { remote } = require('webdriverio');

(async () => {
  const browser = await remote({
    hostname: '127.0.0.1',
    port: 4723,
    path: '/',
    capabilities: {
      platformName: 'iOS',
      'appium:automationName': 'XCUITest',
      'appium:udid': '972BE032-D676-4181-BFD4-07B3B9841186',
      'appium:bundleId': 'xyz.blueskyweb.app',
      'appium:noReset': true,
      'appium:shouldTerminateApp': false,
      'appium:autoLaunch': false,
    },
    logLevel: 'error',
  });

  const size = await browser.getWindowSize();
  console.log('window size:', JSON.stringify(size));

  const x = Math.round(size.width * 0.688);
  const y = Math.round(size.height * 0.935);
  console.log('tapping', x, y);

  await browser.performActions([{
    type: 'pointer',
    id: 'finger1',
    parameters: { pointerType: 'touch' },
    actions: [
      { type: 'pointerMove', duration: 0, x, y },
      { type: 'pointerDown', button: 0 },
      { type: 'pause', duration: 80 },
      { type: 'pointerUp', button: 0 },
    ],
  }]);
  await browser.releaseActions();

  await new Promise(r => setTimeout(r, 2500));
  await browser.deleteSession();
  console.log('done');
})().catch(e => { console.error('ERR', e.message); process.exit(1); });

const { remote } = require('webdriverio');
const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await remote({
    hostname: '127.0.0.1',
    port: 4723,
    path: '/',
    capabilities: {
      platformName: 'iOS',
      'appium:automationName': 'XCUITest',
      'appium:udid': '972BE032-D676-4181-BFD4-07B3B9841186',
      'appium:bundleId': 'xyz.blueskyweb.app',
      'appium:noReset': true,
      'appium:shouldTerminateApp': false,
      'appium:autoLaunch': false,
    },
    logLevel: 'error',
  });

  const hasSheet = async () => /Shared with You/i.test(await browser.getPageSource());
  const dismissSheet = async () => {
    for (let i = 0; i < 3; i++) {
      if (await hasSheet()) {
        await browser.execute('mobile: tap', { x: 196, y: 751 });
        await sleep(1500);
      } else break;
    }
  };

  await dismissSheet();
  await browser.execute('mobile: activateApp', { bundleId: 'xyz.blueskyweb.app' });
  await sleep(2000);
  await dismissSheet();

  const size = await browser.getWindowSize();
  const x = Math.round(size.width * 0.688);
  const y = Math.round(size.height * 0.935);

  for (let attempt = 0; attempt < 3; attempt++) {
    await browser.performActions([{
      type: 'pointer', id: 'f', parameters: { pointerType: 'touch' },
      actions: [
        { type: 'pointerMove', duration: 0, x, y },
        { type: 'pointerDown', button: 0 },
        { type: 'pause', duration: 80 },
        { type: 'pointerUp', button: 0 },
      ],
    }]);
    await browser.releaseActions();
    await sleep(2000);
    if (await hasSheet()) {
      console.log('sheet reappeared, dismissing');
      await dismissSheet();
      await browser.execute('mobile: activateApp', { bundleId: 'xyz.blueskyweb.app' });
      await sleep(2000);
    } else break;
  }

  const shot = await browser.takeScreenshot();
  fs.writeFileSync('/tmp/final.png', Buffer.from(shot, 'base64'));
  await browser.deleteSession();
  console.log('done');
})().catch(e => { console.error('ERR', e.message); process.exit(1); });

const { remote } = require('webdriverio');
const fs = require('fs');

(async () => {
  const browser = await remote({
    hostname: '127.0.0.1',
    port: 4723,
    path: '/',
    capabilities: {
      platformName: 'iOS',
      'appium:automationName': 'XCUITest',
      'appium:udid': '972BE032-D676-4181-BFD4-07B3B9841186',
      'appium:bundleId': 'xyz.blueskyweb.app',
      'appium:noReset': true,
      'appium:shouldTerminateApp': false,
      'appium:autoLaunch': false,
    },
    logLevel: 'error',
  });

  const src = await browser.getPageSource();
  fs.writeFileSync('/tmp/page3.xml', src);
  console.log('page source length:', src.length);

  const btns = await browser.$$('//XCUIElementTypeButton');
  console.log('button count:', btns.length);
  for (const b of btns) {
    try {
      const label = await b.getAttribute('label');
      const rect = await b.getLocation();
      const sz = await b.getSize();
      console.log(JSON.stringify({ label, x: rect.x, y: rect.y, w: sz.width, h: sz.height }));
    } catch (e) {}
  }

  await browser.deleteSession();
  console.log('done');
})().catch(e => { console.error('ERR', e.message); process.exit(1); });
